  private struct VT {
    static let KIND: VOffset = 4
    static let VALUE: VOffset = 6
    static let SIGMA: VOffset = 8
    static let SOURCE_FIELD: VOffset = 10
  }

  public var KIND: asgMeasurementKind { let o = _accessor.offset(VT.KIND); return o == 0 ? .unspecified : asgMeasurementKind(rawValue: _accessor.readBuffer(of: UInt8.self, at: o)) ?? .unspecified }
