  public static func add(KIND: asgMeasurementKind, _ fbb: inout FlatBufferBuilder) { fbb.add(element: KIND.rawValue, def: 0, at: VT.KIND) }
  public static func add(VALUE: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: VALUE, def: 0.0, at: VT.VALUE) }
  public static func add(SIGMA: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: SIGMA, def: 0.0, at: VT.SIGMA) }
  public static func add(SOURCE_FIELD: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SOURCE_FIELD, at: VT.SOURCE_FIELD) }
