  public static func createASGMeasurement(
    _ fbb: inout FlatBufferBuilder,
    KIND: asgMeasurementKind = .unspecified,
    VALUE: Double = 0.0,
    SIGMA: Double = 0.0,
    SOURCE_FIELDOffset SOURCE_FIELD: Offset = Offset()
  ) -> Offset {
    let __start = ASGMeasurement.startASGMeasurement(&fbb)
    ASGMeasurement.add(KIND: KIND, &fbb)
    ASGMeasurement.add(VALUE: VALUE, &fbb)
    ASGMeasurement.add(SIGMA: SIGMA, &fbb)
    ASGMeasurement.add(SOURCE_FIELD: SOURCE_FIELD, &fbb)
    return ASGMeasurement.endASGMeasurement(&fbb, start: __start)
