    try _v.visit(field: VT.KIND, fieldName: "KIND", required: false, type: asgMeasurementKind.self)
    try _v.visit(field: VT.VALUE, fieldName: "VALUE", required: false, type: Double.self)
    try _v.visit(field: VT.SIGMA, fieldName: "SIGMA", required: false, type: Double.self)
