  ///  Mahalanobis distance squared of the residual on S = H P H' + R
  ///  (dimensionless, chi-square distributed with the observation's degrees
  ///  of freedom).
  public var D2: Double { let o = _accessor.offset(VT.D2); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Chi-square upper-tail probability of D2.
  public var P_VALUE: Double { let o = _accessor.offset(VT.P_VALUE); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Posterior association probability among the observation's candidates and
  ///  clutter, 0 to 1.
  public var POSTERIOR: Double { let o = _accessor.offset(VT.POSTERIOR); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
