  public var IN_GATE: Bool { let o = _accessor.offset(VT.IN_GATE); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  Natural logarithm of det(S), in the measurement units' product.
  public var LOG_DET_S: Double { let o = _accessor.offset(VT.LOG_DET_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Residuals, measured minus predicted, one per observation MEASUREMENTS
  ///  entry in the same order and unit (angles wrapped to +-180 degrees).
