  ///  One-way light time applied, s; 0 = none.
  public var LIGHT_TIME_S: Double { let o = _accessor.offset(VT.LIGHT_TIME_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Predicted position at the observation time, GCRF, km (3 values); empty
  ///  when geometry was not requested.
  public var POSITION_GCRF_KM: FlatbufferVector<Double> { return _accessor.vector(at: VT.POSITION_GCRF_KM, byteSize: 8) }
  public func withUnsafePointerToPositionGcrfKm<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.POSITION_GCRF_KM, body: body) }
  ///  Predicted velocity, GCRF, km/s (3 values); empty when not requested.
  public var VELOCITY_GCRF_KM_S: FlatbufferVector<Double> { return _accessor.vector(at: VT.VELOCITY_GCRF_KM_S, byteSize: 8) }
  public func withUnsafePointerToVelocityGcrfKmS<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.VELOCITY_GCRF_KM_S, body: body) }
  ///  Predicted position covariance, GCRF, km**2, 3x3 row-major (9 values);
  ///  empty when not requested.
  public var POSITION_COVARIANCE_KM2: FlatbufferVector<Double> { return _accessor.vector(at: VT.POSITION_COVARIANCE_KM2, byteSize: 8) }
  public func withUnsafePointerToPositionCovarianceKm2<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.POSITION_COVARIANCE_KM2, body: body) }
