  public static func add(D2: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: D2, def: 0.0, at: VT.D2) }
  public static func add(P_VALUE: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: P_VALUE, def: 0.0, at: VT.P_VALUE) }
  public static func add(POSTERIOR: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: POSTERIOR, def: 0.0, at: VT.POSTERIOR) }
  public static func add(IN_GATE: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: IN_GATE, def: false,
   at: VT.IN_GATE) }
  public static func add(LOG_DET_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: LOG_DET_S, def: 0.0, at: VT.LOG_DET_S) }
  public static func addVectorOf(RESIDUAL: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RESIDUAL, at: VT.RESIDUAL) }
  public static func addVectorOf(PREDICTED: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PREDICTED, at: VT.PREDICTED) }
  public static func add(LIGHT_TIME_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: LIGHT_TIME_S, def: 0.0, at: VT.LIGHT_TIME_S) }
  public static func addVectorOf(POSITION_GCRF_KM: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: POSITION_GCRF_KM, at: VT.POSITION_GCRF_KM) }
  public static func addVectorOf(VELOCITY_GCRF_KM_S: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: VELOCITY_GCRF_KM_S, at: VT.VELOCITY_GCRF_KM_S) }
  public static func addVectorOf(POSITION_COVARIANCE_KM2: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: POSITION_COVARIANCE_KM2, at: VT.POSITION_COVARIANCE_KM2) }
  public static func endASGCandidate(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createASGCandidate(
    _ fbb: inout FlatBufferBuilder,
    OBJECTOffset OBJECT: Offset = Offset(),
    D2: Double = 0.0,
    P_VALUE: Double = 0.0,
    POSTERIOR: Double = 0.0,
    IN_GATE: Bool = false,
    LOG_DET_S: Double = 0.0,
    RESIDUALVectorOffset RESIDUAL: Offset = Offset(),
    PREDICTEDVectorOffset PREDICTED: Offset = Offset(),
    LIGHT_TIME_S: Double = 0.0,
    POSITION_GCRF_KMVectorOffset POSITION_GCRF_KM: Offset = Offset(),
    VELOCITY_GCRF_KM_SVectorOffset VELOCITY_GCRF_KM_S: Offset = Offset(),
    POSITION_COVARIANCE_KM2VectorOffset POSITION_COVARIANCE_KM2: Offset = Offset()
  ) -> Offset {
    let __start = ASGCandidate.startASGCandidate(&fbb)
    ASGCandidate.add(OBJECT: OBJECT, &fbb)
    ASGCandidate.add(D2: D2, &fbb)
    ASGCandidate.add(P_VALUE: P_VALUE, &fbb)
    ASGCandidate.add(POSTERIOR: POSTERIOR, &fbb)
    ASGCandidate.add(IN_GATE: IN_GATE, &fbb)
    ASGCandidate.add(LOG_DET_S: LOG_DET_S, &fbb)
    ASGCandidate.addVectorOf(RESIDUAL: RESIDUAL, &fbb)
    ASGCandidate.addVectorOf(PREDICTED: PREDICTED, &fbb)
    ASGCandidate.add(LIGHT_TIME_S: LIGHT_TIME_S, &fbb)
    ASGCandidate.addVectorOf(POSITION_GCRF_KM: POSITION_GCRF_KM, &fbb)
    ASGCandidate.addVectorOf(VELOCITY_GCRF_KM_S: VELOCITY_GCRF_KM_S, &fbb)
    ASGCandidate.addVectorOf(POSITION_COVARIANCE_KM2: POSITION_COVARIANCE_KM2, &fbb)
    return ASGCandidate.endASGCandidate(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.OBJECT, fieldName: "OBJECT", required: false, type: ForwardOffset<ASGObjectRef>.self)
    try _v.visit(field: VT.D2, fieldName: "D2", required: false, type: Double.self)
    try _v.visit(field: VT.P_VALUE, fieldName: "P_VALUE", required: false, type: Double.self)
    try _v.visit(field: VT.POSTERIOR, fieldName: "POSTERIOR", required: false, type: Double.self)
    try _v.visit(field: VT.IN_GATE, fieldName: "IN_GATE", required: false, type: Bool.self)
    try _v.visit(field: VT.LOG_DET_S, fieldName: "LOG_DET_S", required: false, type: Double.self)
    try _v.visit(field: VT.RESIDUAL, fieldName: "RESIDUAL", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.PREDICTED, fieldName: "PREDICTED", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.LIGHT_TIME_S, fieldName: "LIGHT_TIME_S", required: false, type: Double.self)
    try _v.visit(field: VT.POSITION_GCRF_KM, fieldName: "POSITION_GCRF_KM", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.VELOCITY_GCRF_KM_S, fieldName: "VELOCITY_GCRF_KM_S", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.POSITION_COVARIANCE_KM2, fieldName: "POSITION_COVARIANCE_KM2", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    _v.finish()
  }
}

